// NodeServiceServer is the server API for NodeService service.
// All implementations should embed UnimplementedNodeServiceServer
// for forward compatibility.
//
// NodeService is the Phase 1 management surface for a single CryptOS node.
// All RPCs are served over mTLS gRPC on port 443 of the management
// interface, plus a local UNIX socket for on-box cryptosctl access.
//
// Phase 1 ships exactly these RPCs. Phase 2 splits SignCSR into
// role-restricted RPCs and adds protocol-adapter management.
type NodeServiceServer interface {
	// ApplyConfig sets the node's declarative machine configuration.
	// Returns requires_reboot=true when the change cannot take effect at runtime.
	ApplyConfig(context.Context, *ApplyConfigRequest) (*ApplyConfigResponse, error)
	// GetStatus returns node role, identity state, and subsystem health.
	GetStatus(context.Context, *GetStatusRequest) (*GetStatusResponse, error)
	// ListInstallDisks enumerates the node's candidate install block devices
	// (whole disks, not partitions), so an operator adopting the node can pick a
	// real target device instead of guessing a path. Served in maintenance mode.
	ListInstallDisks(context.Context, *ListInstallDisksRequest) (*ListInstallDisksResponse, error)
	// GetIdentity returns the node's CA certificate chain in DER and PEM.
	GetIdentity(context.Context, *GetIdentityRequest) (*GetIdentityResponse, error)
	// StartCeremony drives the first-boot ceremony. Operator-initiated;
	// streams progress events until completion. Only valid when the node
	// is in the no-identity state.
	StartCeremony(*StartCeremonyRequest, grpc.ServerStreamingServer[StartCeremonyResponse]) error
	// SignCSR signs a Certificate Signing Request with the Root CA key.
	// Phase 1 debug-only: included only in builds compiled with
	// -tags=debug_signcsr. Phase 2 replaces this with role-restricted
	// RPCs (Root.SignSubordinateCSR and an internal Issuing.IssueLeaf).
	SignCSR(context.Context, *SignCSRRequest) (*SignCSRResponse, error)
	// SignSubordinateCSR signs a child CA's CSR into a CA certificate per a
	// named profile (BasicConstraints CA:TRUE, pathLen clamped to the parent's
	// budget) and returns the new cert plus the parent's chain. Role-restricted
	// (a CA that may sign sub-CAs) and authorized by the bootstrap admin;
	// reachable online (parent mTLS) or offline (operator ferry via the local
	// socket). Supersedes the debug-only SignCSR for the CA path.
	SignSubordinateCSR(context.Context, *SignSubordinateCSRRequest) (*SignSubordinateCSRResponse, error)
	// IssueLeaf signs an end-entity (CA:FALSE) certificate per a named profile.
	// Role-restricted (intermediate/issuing; a root only with the irreversible
	// ack). The internal path the Phase-2 protocol adapters will call.
	IssueLeaf(context.Context, *IssueLeafRequest) (*IssueLeafResponse, error)
	// GetSubordinateCSR returns the CSR a subordinate node generated on first
	// boot, while it is in IDENTITY_STATE_AWAITING_CERT. The operator carries it
	// to the parent's SignSubordinateCSR (Refused unless awaiting a cert).
	GetSubordinateCSR(context.Context, *GetSubordinateCSRRequest) (*GetSubordinateCSRResponse, error)
	// SubmitSubordinateCertificate hands a subordinate node the parent-signed
	// certificate + chain. The node verifies the chain roots to its configured
	// parent trust anchor (pki.parent) and that the leaf matches its own key,
	// then commits and becomes ESTABLISHED. Returns the committed identity.
	SubmitSubordinateCertificate(context.Context, *SubmitSubordinateCertificateRequest) (*SubmitSubordinateCertificateResponse, error)
	// RevokeCertificate marks a certificate this node issued (identified by its
	// hex serial) as revoked with an RFC 5280 reason, records it, and refreshes
	// the CRL. Admin-authorized. NotFound if the serial is not in this node's
	// issued set. Idempotent: re-revoking returns the existing revocation.
	RevokeCertificate(context.Context, *RevokeCertificateRequest) (*RevokeCertificateResponse, error)
	// ListIssued returns the certificates this node has issued, for inventory
	// and for the Fleet Manager to drive revocation.
	ListIssued(context.Context, *ListIssuedRequest) (*ListIssuedResponse, error)
	// ListRevocations returns this node's revoked certificates.
	ListRevocations(context.Context, *ListRevocationsRequest) (*ListRevocationsResponse, error)
	// GetIssuedCertificate returns a certificate this node issued, identified by
	// its hex serial, with its chain and current status, so a client can fetch
	// the certificate itself rather than only its inventory entry. NotFound if
	// the serial is not in this node's issued set.
	GetIssuedCertificate(context.Context, *GetIssuedCertificateRequest) (*GetIssuedCertificateResponse, error)
	// ExportCAKey returns an encrypted backup of this node's software CA key and
	// certificate chain, sealed under the operator passphrase. The plaintext key
	// never leaves the node. Admin-authorized; refused on a TPM node (TPM keys
	// are non-exportable by design).
	ExportCAKey(context.Context, *ExportCAKeyRequest) (*ExportCAKeyResponse, error)
	// ImportCAKey restores a CA from an encrypted backup: it is the recovery
	// counterpart of StartCeremony, valid only on a node whose storage is up but
	// which has no identity yet. It decrypts the envelope with the passphrase and
	// commits the restored key + chain, becoming ESTABLISHED as the same CA.
	ImportCAKey(context.Context, *ImportCAKeyRequest) (*ImportCAKeyResponse, error)
	// BeginKeyRotation starts a subordinate CA key rotation: the established
	// intermediate/issuing node generates a new key and returns a CSR to ferry to
	// the parent, while continuing to sign with its current key. Admin-authorized;
	// refused on a root or a node with no identity.
	BeginKeyRotation(context.Context, *BeginKeyRotationRequest) (*BeginKeyRotationResponse, error)
	// CompleteKeyRotation submits the parent-signed chain for the new key. The
	// node verifies it roots to the pinned parent and matches the staged new key,
	// then atomically swaps to the new key + cert. Certificates the old key signed
	// remain valid until they expire.
	CompleteKeyRotation(context.Context, *CompleteKeyRotationRequest) (*CompleteKeyRotationResponse, error)
	// GetRenewalCSR returns a CSR signed by the established subordinate's CURRENT
	// CA key, with the subject copied from its current CA certificate, so the
	// parent can issue a fresh certificate for the same key (for example one that
	// now carries CRL and OCSP pointers). Nothing is staged. Admin-authorized;
	// refused on a root or a node with no identity.
	GetRenewalCSR(context.Context, *GetRenewalCSRRequest) (*GetRenewalCSRResponse, error)
	// SubmitRenewedCertificate submits the parent-signed chain for the node's
	// current key. The node verifies it roots to the pinned parent, carries the
	// same public key, subject and subject key identifier as the current CA
	// certificate, and is a CA certificate whose path length is not wider, then
	// atomically replaces its CA certificate and keeps the previous one for
	// audit. Takes effect without a reboot; certificates the node already issued
	// keep verifying.
	SubmitRenewedCertificate(context.Context, *SubmitRenewedCertificateRequest) (*SubmitRenewedCertificateResponse, error)
	// Reset destroys the node's identity: it erases the state-partition key
	// material (rendering all encrypted data unrecoverable), clears any staged
	// config, and reboots into maintenance. Served ONLY on the local UNIX
	// socket (physical-console trust); the node refuses it over mTLS and in
	// maintenance mode. The caller must echo the current Root CA CN as
	// confirmation.
	Reset(context.Context, *ResetRequest) (*ResetResponse, error)
	// RemoteReset performs the same destructive wipe as Reset but is served over
	// mTLS, admin-authorized, for manager-mediated decommission. It is the remote
	// counterpart of the local-only Reset: same destructive path (Resetter +
	// reboot into maintenance), reachable by an authenticated admin instead of
	// only the physical console. The caller must echo the current Root CA CN.
	RemoteReset(context.Context, *RemoteResetRequest) (*RemoteResetResponse, error)
	// Attest signs the caller's nonce with the node's CA identity key so the
	// Fleet Manager can verify possession of the node identity (challenge-
	// response). The nonce is domain-separated before signing (see
	// AttestResponse.signature), so an Attest signature can never be replayed
	// as a certificate, CRL or OCSP signature. ek_pub/ek_cert are reserved for
	// future TPM EK attestation.
	Attest(context.Context, *AttestRequest) (*AttestResponse, error)
	// SetManagement merges FM managed-state into the node's persisted config
	// (read-modify-write on the node) without replacing the whole config; used by
	// a LINK enrollment approval. Clearing management (nil) unlinks.
	SetManagement(context.Context, *SetManagementRequest) (*SetManagementResponse, error)
	// GetConfig returns the node's current machine configuration. A caller reads
	// the full config here, edits a subset, and applies the whole config back via
	// ApplyConfig (a whole-config replace), so untouched fields survive.
	GetConfig(context.Context, *GetConfigRequest) (*GetConfigResponse, error)
	// StageImage installs a new CryptOS image on the node without re-provisioning
	// it. Until now the only way to change the OS was a reinstall, which reformats
	// the state partition and destroys the CA key with it; the image lives on the
	// ESP and identity lives on a separate LUKS partition, so replacing one need
	// not touch the other. This RPC never opens the state partition.
	//
	// Client-streaming because a UKI carries a whole SquashFS root filesystem and
	// does not belong in a single message. The first message must be the begin
	// header; every later message carries a chunk. The node verifies the detached
	// release signature over the assembled bytes before anything reaches the disk,
	// so an image it cannot attribute is never written.
	//
	// Staging does not reboot. The image becomes the one the firmware boots on the
	// next boot, and the node keeps the image it is running so the change can be
	// undone; call ActivateImage when the outage is acceptable.
	StageImage(grpc.ClientStreamingServer[StageImageRequest, StageImageResponse]) error
	// RollbackImage puts the retained previous image back on the boot path, for an
	// upgrade that turned out badly. Like staging it does not reboot, and like
	// staging it takes effect on the next boot.
	RollbackImage(context.Context, *RollbackImageRequest) (*RollbackImageResponse, error)
	// ActivateImage reboots the node so a staged image starts running. It is a
	// separate call because rebooting an issuing CA is an outage of the thing
	// every other system depends on, and that is the operator's decision to time,
	// not a side effect of an upload. The caller must echo the node's CA CN, the
	// same confirmation Reset and RemoteReset require.
	ActivateImage(context.Context, *ActivateImageRequest) (*ActivateImageResponse, error)
	// GetImageStatus reports what is installed on the ESP and what is running, so
	// an operator can tell whether an upgrade took and whether a reboot is still
	// pending.
	GetImageStatus(context.Context, *GetImageStatusRequest) (*GetImageStatusResponse, error)
	// Reboot restarts or powers off the node through an orderly shutdown: the
	// listeners stop, the stores flush and close, and the state volume is
	// unmounted and locked before the kernel is asked to restart. It is how a
	// change that ApplyConfig reported as requires_reboot takes effect without a
	// hypervisor hard reset, which skips all of that. Admin-authorized over mTLS
	// and served on the local socket; refused in maintenance mode. The caller
	// must echo the node's CA CN, the same confirmation ActivateImage requires.
	Reboot(context.Context, *RebootRequest) (*RebootResponse, error)
	// MintScepChallenge creates a single-use challenge for one initial
	// enrolment and returns it. The challenge is returned by this call only: the
	// node stores a digest of it and no RPC reads it back, so a lost challenge is
	// revoked and minted again. It is consumed by the first PKCSReq that
	// presents it, whether that request is issued, refused or queued.
	MintScepChallenge(context.Context, *MintScepChallengeRequest) (*MintScepChallengeResponse, error)
	// ListScepChallenges returns the challenges that are still usable: minted,
	// not yet consumed, not revoked and not expired. It never carries the
	// challenge or its digest.
	ListScepChallenges(context.Context, *ListScepChallengesRequest) (*ListScepChallengesResponse, error)
	// RevokeScepChallenge withdraws a usable challenge by id before it is
	// consumed. NotFound when the id is unknown, already consumed, revoked or
	// expired.
	RevokeScepChallenge(context.Context, *RevokeScepChallengeRequest) (*RevokeScepChallengeResponse, error)
	// ListScepEnrollments returns the initial enrolments waiting for an admin
	// decision on profiles with require_approval set, oldest first.
	ListScepEnrollments(context.Context, *ListScepEnrollmentsRequest) (*ListScepEnrollmentsResponse, error)
	// ApproveScepEnrollment issues the certificate for a waiting enrolment under
	// its profile and returns its serial. The client collects it with its next
	// CertPoll. NotFound when the id is not waiting. The request is checked
	// again at approval, against the config and key floor in force then, and a
	// request that no longer passes is refused with FailedPrecondition and stays
	// queued for rejection.
	ApproveScepEnrollment(context.Context, *ApproveScepEnrollmentRequest) (*ApproveScepEnrollmentResponse, error)
	// RejectScepEnrollment refuses a waiting enrolment. The client's next
	// CertPoll is answered FAILURE. NotFound when the id is not waiting.
	RejectScepEnrollment(context.Context, *RejectScepEnrollmentRequest) (*RejectScepEnrollmentResponse, error)
	// ListTsaCertificates returns every TSA certificate the node has signed
	// timestamp tokens with, the current one and all past ones, newest first,
	// so a relying party can verify a token signed before a rotation. It is a
	// read, authorized like ListIssued, and it answers whether or not the TSA is
	// running this boot: switching the TSA off does not unpublish the
	// certificates old tokens name. Empty on a node that has never run a TSA.
	// Refused with FailedPrecondition in maintenance mode.
	ListTsaCertificates(context.Context, *ListTsaCertificatesRequest) (*ListTsaCertificatesResponse, error)
	// ListAuditEvents returns audit log entries, oldest first, a page at a time,
	// filtered by time range, event type and actor.
	ListAuditEvents(context.Context, *ListAuditEventsRequest) (*ListAuditEventsResponse, error)
	// VerifyAuditChain verifies the signatures and hash chain over the whole
	// stored audit log and reports whether it is intact and, if not, the first
	// sequence number that failed.
	VerifyAuditChain(context.Context, *VerifyAuditChainRequest) (*VerifyAuditChainResponse, error)
}

